<script setup lang="ts">import {computed,ref} from 'vue';type Option={label:string;value:string};const p=withDefaults(defineProps<{modelValue?:string[];options?:Option[];label?:string}>(),{modelValue:()=>[],options:()=>[]});const emit=defineEmits<{'update:modelValue':[v:string[]]}>();const query=ref('');const matches=computed(()=>(p.options ?? []).filter(x=>x.label.toLowerCase().includes(query.value.toLowerCase())));function toggle(v:string){emit('update:modelValue',(p.modelValue ?? []).includes(v)?(p.modelValue ?? []).filter(x=>x!==v):[...(p.modelValue ?? []),v])}</script><template><fieldset class="vx-multi"><legend>{{label||'Select options'}}</legend><input v-model="query" class="vx-control" type="search" placeholder="Search options"/><div class="vx-multi__list"><label v-for="o in matches" :key="o.value"><input type="checkbox" :checked="(modelValue ?? []).includes(o.value)" @change="toggle(o.value)"/>{{o.label}}</label><p v-if="!matches.length">No matching options</p></div></fieldset></template>